import { runBelongsToMaidContext } from '../agent/maid-run-followup.js';

// Resolve IDs only through successful receipts owned by this card. Model input
// never supplies a file path. Generated bytes already saved by the media service
// are reused; downloaded images use the existing reference store.
export const createMaidMediaAttachmentPersistence = ({ getReferenceStore, listRuns, logger = console } = {}) => ({
  persist: async (attachment, context, storedImage = null) => {
    if (!context?.roleCardId || !context.runId) return null;
    try {
      const sessionId = `maid-media-${context.roleCardId}`;
      const reference = storedImage?.path ? storedImage
        : (await getReferenceStore().persist([attachment], sessionId))[0];
      if (!reference?.path) return null;
      return { version: 1, roleCardId: context.roleCardId,
        reference: { path: reference.path, sessionId: reference.sessionId || sessionId,
          name: attachment.name, mime: attachment.mime, bytes: attachment.bytes } };
    } catch (error) {
      logger?.warn?.('maid media reference could not be saved', error);
      return null; // Keep the paid image usable in this running task.
    }
  },
  load: async (attachmentId, context) => {
    if (!attachmentId || !context?.roleCardId) return null;
    for (const run of listRuns()) {
      if (!runBelongsToMaidContext(run, context)) continue;
      for (const step of run.steps || []) {
        const result = step.output?.result, saved = result?.attachmentReference;
        if (!['media.generate_image', 'media.fetch_image'].includes(step.input?.toolName)
          || step.status !== 'succeeded' || result?.ok !== true || result.attachmentId !== attachmentId
          || saved?.version !== 1 || saved.roleCardId !== context.roleCardId || !saved.reference?.path) continue;
        try {
          const [image] = await getReferenceStore().load([saved.reference], saved.reference.sessionId);
          if (!image?.dataUrl?.startsWith('data:image/')) return null;
          return { id: attachmentId, url: image.dataUrl, name: result.name, mime: result.mime,
            bytes: result.bytes, visualSpec: result.visualSpec, roleCardId: context.roleCardId };
        } catch (error) {
          logger?.debug?.('maid media attachment unavailable', error);
          return null;
        }
      }
    }
    return null;
  },
});
